import time
from collections import defaultdict, deque
import math

class TimeseriesRollupEngine:
    def __init__(self):
        # Stores a deque of tuples: (timestamp, value) for each metric name
        self.metrics = defaultdict(deque)

    def record(self, metric: str, val: float, ts: float) -> None:
        """
        Record a metric value at a specific timestamp.
        """
        self.metrics[metric].append((ts, val))

    def query_rollup(self, metric: str, window_sec: float, agg_func: str) -> float:
        """
        Query the rollup for a given metric over a sliding window (in seconds) 
        ending at the maximum timestamp present in the metric's records.

        Supported agg_func: 'avg', 'max', 'min', 'p95'
        """
        if metric not in self.metrics or not self.metrics[metric]:
            return 0.0

        records = self.metrics[metric]

        # The window ends at the latest timestamp recorded for this metric
        latest_ts = records[-1][0]
        cutoff_ts = latest_ts - window_sec

        # Filter values within the sliding window [cutoff_ts, latest_ts]
        # Since records are appended chronologically, we can filter efficiently.
        values = [val for ts, val in records if ts >= cutoff_ts]

        if not values:
            return 0.0

        if agg_func == 'avg':
            return sum(values) / len(values)
        elif agg_func == 'max':
            return max(values)
        elif agg_func == 'min':
            return min(values)
        elif agg_func == 'p95':
            sorted_vals = sorted(values)
            # Using nearest-rank method for p95
            index = int(math.ceil(0.95 * len(sorted_vals))) - 1
            index = max(0, min(index, len(sorted_vals) - 1))
            return sorted_vals[index]
        else:
            raise ValueError(f"Unsupported aggregation function: {agg_func}")
